resource "google_container_cluster" "gke" {
  name               = var.name
  location           = var.location
  initial_node_count = var.inital_node_count
  release_channel {
    channel = var.release_channel
  }

  networking_mode = "VPC_NATIVE"
  network         = var.network
  subnetwork      = var.subnetwork

  ip_allocation_policy {
    cluster_secondary_range_name  = var.pod_range_name
    services_secondary_range_name = var.service_range_name
  }

  private_cluster_config {
    enable_private_nodes    = var.enable_private_nodes
    enable_private_endpoint = var.enable_private_endpoint
    master_global_access_config {
      enabled = var.master_global_access_config
    }
  }

  remove_default_node_pool = var.remove_default_node_pool

  workload_identity_config {
    workload_pool = "${var.project_id}.svc.id.goog"
  }

  vertical_pod_autoscaling {
    enabled = true
  }

  maintenance_policy {
    recurring_window {
      start_time = var.recurring_window.start_time
      end_time   = var.recurring_window.end_time
      recurrence = var.recurring_window.recurrence
    }
  }
  dns_config {
    cluster_dns       = var.dns_config.cluster_dns
    cluster_dns_scope = var.dns_config.cluster_dns_scope
  }
  datapath_provider = var.datapath_provider
  addons_config {
    dns_cache_config {
      enabled = true
    }
  }
}

resource "google_container_node_pool" "default_pool" {
  name           = "${var.name}-default-pool"
  location       = var.location
  cluster        = google_container_cluster.gke.name
  node_locations = var.node_locations # Aquí se definen las ubicaciones de los nodos

  node_count = var.node_count # Aquí se define la cantidad de nodos fijos

  management {
    auto_upgrade = true
    auto_repair  = true
  }

  node_config {
    machine_type    = var.machine_type
    disk_size_gb    = var.disk_size_gb
    disk_type       = var.disk_type
    service_account = var.service_account

    oauth_scopes = [
      "https://www.googleapis.com/auth/cloud-platform"
    ]

    labels = var.labels

    tags = var.network_tags
  }
}

resource "google_gke_backup_backup_plan" "backup" {
  count    = var.backup_plan_enabled ? 1 : 0
  name     = coalesce(var.backup_plan_config.name, "${var.name}-backup-plan")
  cluster  = google_container_cluster.gke.id
  location = var.location
  project  = var.project_id

  retention_policy {
    backup_retain_days = var.backup_plan_config.retention_days
  }

  backup_schedule {
    cron_schedule = var.backup_plan_config.cron_schedule
    paused        = var.backup_plan_config.paused
  }

  backup_config {
    include_volume_data = true
    include_secrets     = true
    all_namespaces      = true
  }
}

resource "google_gke_backup_restore_plan" "restore" {
  count       = var.restore_plan_enabled && var.backup_plan_enabled ? 1 : 0
  name        = coalesce(var.restore_plan_config.name, "${var.name}-restore-plan")
  location    = var.location
  project     = var.project_id
  backup_plan = google_gke_backup_backup_plan.backup[0].id
  cluster     = google_container_cluster.gke.id

  restore_config {
    all_namespaces                   = true
    namespaced_resource_restore_mode = var.restore_plan_config.namespaced_resource_restore_mode
    volume_data_restore_policy       = var.restore_plan_config.volume_data_restore_policy
    cluster_resource_conflict_policy = var.restore_plan_config.cluster_resource_conflict_policy

    cluster_resource_restore_scope {
      all_group_kinds = true
    }
  }
}

