}
variable "pod_range_name" {
  type        = string
  description = "Nombre del rango de IPs para los pods"
}
variable "service_range_name" {
  type        = string
  description = "Nombre del rango de IPs para los servicios"
}

variable "machine_type" {
  type        = string
  description = "Tipo de máquina para los nodos"
}

variable "disk_size_gb" {
  type        = number
  description = "Tamaño del disco en GB para los nodos"
  default     = 100
}

variable "disk_type" {
  type        = string
  description = "Tipo de disco para los nodos"
  default     = "pd-ssd"
}

variable "labels" {
  type        = map(string)
  description = "Etiquetas para los nodos"
  default     = {}

}

variable "network_tags" {
  type    = list(string)
  default = []
}

variable "location" {
  type        = string
  description = "Ubicación del clúster"
}

variable "node_locations" {
  type        = list(string)
  description = "Ubicaciones de los nodos"
}

variable "project_id" {
  type        = string
  description = "ID del proyecto de GCP"
}

variable "name" {
  type        = string
  description = "Nombre del clúster"
}

variable "service_account" {
  type        = string
  description = "Cuenta de servicio para los nodos"
}

variable "release_channel" {
  type        = string
  description = "Canal de lanzamiento del clúster"
  default     = "REGULAR"
}

variable "inital_node_count" {
  type        = number
  description = "Número de nodos iniciales"
  default     = 1
}

variable "enable_private_nodes" {
  type        = bool
  description = "Indica si se deben habilitar los nodos privados"
  default     = true
}

variable "enable_private_endpoint" {
  type        = bool
  description = "Indica si se debe habilitar el punto de conexión privado"
  default     = false
}

variable "master_global_access_config" {
  type        = bool
  description = "Indica si se debe habilitar el acceso global al maestro"
  default     = false
}

variable "remove_default_node_pool" {
  type        = bool
  description = "Indica si se debe eliminar el nodo por defecto"
  default     = true
}

variable "recurring_window" {
  type = object({
    start_time = string
    end_time   = string
    recurrence = string
  })
  description = "Ventana de mantenimiento recurrente"
  default = {
    start_time = "2025-08-24T05:00:00Z" # UTC = 12 a.m. GMT-5
    end_time   = "2025-08-24T17:00:00Z" # UTC = 12 p.m. GMT-5
    recurrence = "FREQ=WEEKLY;BYDAY=SU"
  }
}

